"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";

export default function HeroScene3D() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // --- 1. SCENE SETUP ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xffffff);

    const width = container.clientWidth;
    const height = container.clientHeight;

    // --- 2. CAMERA SETUP ---
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
    camera.position.set(0, 0, 8.8);

    // --- 3. RENDERER SETUP ---
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance",
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    container.appendChild(renderer.domElement);

    // --- 4. LIGHTING ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 1.2);
    scene.add(ambientLight);

    const keyLight = new THREE.DirectionalLight(0xffffff, 0.8);
    keyLight.position.set(5, 5, 5);
    scene.add(keyLight);

    // Group that will hold the avatar & rotate to face mouse
    const worldGroup = new THREE.Group();
    scene.add(worldGroup);

    const avatarGroup = new THREE.Group();
    worldGroup.add(avatarGroup);

    // --- 5. TEXTURE & AVATAR MESH (ENLARGED) ---
    const textureLoader = new THREE.TextureLoader();
    const avatarAspect = 1536 / 2730; // ~0.5626
    const planeHeight = 6.6; // Increased from 5.2 for a larger, prominent avatar
    const planeWidth = planeHeight * avatarAspect; // ~3.71

    let avatarMesh: THREE.Mesh | null = null;
    let geometry: THREE.PlaneGeometry | null = null;
    let material: THREE.MeshBasicMaterial | null = null;

    textureLoader.load(
      "/images/Hero-avatar1.webp",
      (texture) => {
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearFilter;
        texture.generateMipmaps = true;

        geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
        geometry.translate(0, planeHeight * 0.4, 0);

        material = new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          side: THREE.DoubleSide,
          depthWrite: false,
        });

        avatarMesh = new THREE.Mesh(geometry, material);
        // Position the pivot point (feet) so the overall avatar stays centered on screen
        avatarGroup.position.set(0, -planeHeight * 0.4, 0);
        avatarGroup.add(avatarMesh);

        setIsLoaded(true);
      }
    );

    // --- 6. MOUSE TRACKING & INTERPOLATION ---
    const mouse = { x: 0, y: 0, targetX: 0, targetY: 0 };

    const onMouseMove = (e: MouseEvent) => {
      mouse.targetX = (e.clientX / window.innerWidth) * 2 - 1;
      mouse.targetY = -(e.clientY / window.innerHeight) * 2 + 1;
    };

    const onTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        const touch = e.touches[0];
        mouse.targetX = (touch.clientX / window.innerWidth) * 2 - 1;
        mouse.targetY = -(touch.clientY / window.innerHeight) * 2 + 1;
      }
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("touchmove", onTouchMove, { passive: true });

    // --- 7. RESIZE HANDLER ---
    const onResize = () => {
      if (!container) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;

      if (w < 768) {
        camera.position.z = 10.5;
      } else {
        camera.position.z = 8.8;
      }

      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };

    window.addEventListener("resize", onResize);
    onResize();

    // --- 8. ANIMATION LOOP ---
    let animationFrameId: number;

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      // Smooth lerp damping
      mouse.x += (mouse.targetX - mouse.x) * 0.055;
      mouse.y += (mouse.targetY - mouse.y) * 0.055;

      // 3D Rotation: Pure twist without any sideways lean
      avatarGroup.rotation.y = mouse.x * 0.08; // Pure twist/rotate
      avatarGroup.rotation.x = -mouse.y * 0.08; // Subtle forward/back tilt
      avatarGroup.rotation.z = 0; // Removed sideways lean completely

      // Environment / Camera: Fixed horizontally to prevent perspective leaning
      camera.position.x = 0;
      camera.position.y = mouse.y * 0.22;
      camera.lookAt(0, 0, 0);

      renderer.render(scene, camera);
    };

    animate();

    // --- 9. CLEANUP ---
    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("resize", onResize);

      if (container && renderer.domElement.parentNode === container) {
        container.removeChild(renderer.domElement);
      }

      renderer.dispose();
      geometry?.dispose();
      material?.dispose();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className={`relative w-full h-screen transition-opacity duration-700 ${isLoaded ? "opacity-100" : "opacity-0"
        }`}
    />
  );
}
